def test_aes_256_gcm():
    for key, iv, plaintext, associated, ciphertext, tag in vectors("aes-256-gcm"):
        sealed = crypto.aes_256_gcm_encrypt(unhex(key), unhex(iv), unhex(plaintext), unhex(associated))
