        assert crypto.aes_256_gcm_decrypt(unhex(key), unhex(iv), sealed, unhex(associated)) == unhex(plaintext)
        tampered = bytes([sealed[0] ^ 1]) + sealed[1:]
        assert crypto.aes_256_gcm_decrypt(unhex(key), unhex(iv), tampered, unhex(associated)) is None


