def test_slh_dsa_shake_128f_round_trip():
    for sk_seed, sk_prf, pk_seed, _, _ in vectors("slhdsa128f-keygen"):
        public, secret = crypto.slh_dsa_key_pair(unhex(sk_seed), unhex(sk_prf), unhex(pk_seed))
        signature = crypto.slh_dsa_sign(secret, b"LawSpec")
        assert crypto.slh_dsa_verify(public, b"LawSpec", signature)
        assert not crypto.slh_dsa_verify(public, b"LawSpeC", signature)
